/* Local cache is never presented as saved shared progress. SQLite is authoritative. */
window.ProgressSync=(function(){
let pending=[],snapshot={records:{},revisions:{},version:-1},busy=false,connected=false,lastLocal={},conflicted=false,legacy=null,lastFailure='';
const clone=x=>JSON.parse(JSON.stringify(x)),key=op=>`${op.day}|${op.problem}|${op.field}`;
function persist(){try{localStorage.setItem('slow-think-v2-pending',JSON.stringify(pending));localStorage.setItem('slow-think-v2-cache',JSON.stringify(snapshot))}catch{}}
function id(){return Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}
async function request(path,data){let timer;const controller=typeof AbortController!=='undefined'?new AbortController():null;const options=data?{method:'POST',headers:{'Content-Type':'application/json','X-Learning-Request':'1'},body:JSON.stringify(data)}:{};if(controller)options.signal=controller.signal;const network=(async()=>{const r=await fetch(path,options);const body=await r.json();if(!r.ok){const e=Error('sync');e.status=r.status;e.body=body;throw e}return body})();const deadline=new Promise((_,reject)=>{timer=setTimeout(()=>{const e=Error('timeout');e.timeout=true;reject(e);if(controller)controller.abort()},6000)});try{const result=await Promise.race([network,deadline]);lastFailure='';return result}catch(e){lastFailure=e.timeout?'连接超时（6秒）':e.status?'服务响应 HTTP '+e.status:'网络或接口响应异常';throw e}finally{clearTimeout(timer)}}
function status(){const el=document.getElementById('sync-status');if(!el)return;el.innerHTML=conflicted?'另一端更改了记录。你的待提交更改已保留。 <button id="keep-server">使用共享版本</button><button id="keep-local">保留我的更改</button>':connected?(pending.length?'更改待保存…':'已保存到共享记录'):'离线 · 更改尚未保存到共享记录'+(lastFailure?' · '+lastFailure:'');if(legacy)el.insertAdjacentHTML('beforeend','<div class="import-notice">发现旧浏览器记录。只补充服务端缺失项，已有服务端值优先，旧记录保留。<button id="import-legacy">导入旧记录</button></div>');if(document.getElementById('keep-server'))document.getElementById('keep-server').onclick=()=>{pending=[];conflicted=false;accept(snapshot,true)};if(document.getElementById('keep-local'))document.getElementById('keep-local').onclick=()=>{const rev={...snapshot.revisions};for(const op of pending){const fieldKey=op.field==='planned'?'plan|'+op.problem:key(op);op.revision=rev[fieldKey]??(op.field==='planned'?snapshot.planRevisions?.[op.problem]:0)??0;rev[fieldKey]=op.revision+1}conflicted=false;persist();flush()};if(document.getElementById('import-legacy'))document.getElementById('import-legacy').onclick=async()=>{try{accept(await request('/api/import',{records:legacy}),true);localStorage.setItem('slow-think-v2-imported','1');legacy=null;status()}catch{connected=false;status()}}}
function overlay(base){const result=clone(base);let plan=Array.isArray(snapshot.plan)?snapshot.plan.slice():null;for(const op of pending){const r=result[op.day]||(result[op.day]={list:[],done:[]});const k=op.field==='planned'?'list':'done';r[k]=r[k].filter(x=>x!==op.problem);if(op.value)r[k].push(op.problem);if(plan&&op.field==='planned'){plan=plan.filter(x=>x!==op.problem);if(op.value)plan.push(op.problem)}}if(plan){const d=day();result[d]=result[d]||{list:[],done:[]};result[d].list=plan}return result}
function accept(next,rerender){snapshot=next;records=overlay(next.records);lastLocal=clone(records);connected=true;persist();if(rerender&&!currentId)render();if(currentId&&lessons[currentId]&&document.getElementById('done'))document.getElementById('done').textContent=today().done.includes(currentId)?'取消「已理解」':'标记已理解';status()}
async function flush(){if(busy||conflicted)return;busy=true;try{if(pending.length){const batch=pending.slice();const next=await request('/api/progress',{operations:batch});pending=pending.filter(op=>!batch.some(sent=>sent.id===op.id));accept(next,false);if(document.getElementById('done-status'))document.getElementById('done-status').textContent='已保存到共享记录。'}else{const next=await request('/api/progress');accept(next,next.version!==snapshot.version)}}catch(e){if(e.status===409){snapshot=e.body.snapshot;conflicted=true;connected=true;persist()}else connected=false;status();if(document.getElementById('done-status'))document.getElementById('done-status').textContent=conflicted?'与另一端冲突，请选择保留哪个版本。':'尚未保存，更改已留在待同步队列。'}finally{busy=false}}
function save(next){for(const day of new Set([...Object.keys(lastLocal),...Object.keys(next)])){for(const [k,field] of [['list','planned'],['done','done']]){const before=lastLocal[day]?.[k]||[],after=next[day]?.[k]||[];for(const problem of new Set([...before,...after]))if(before.includes(problem)!==after.includes(problem)){const op={id:id(),day,problem,field,value:after.includes(problem)};const earlier=pending.filter(p=>key(p)===key(op));op.revision=earlier.length?earlier[earlier.length-1].revision+1:(field==='planned'?snapshot.planRevisions?.[problem]:snapshot.revisions?.[key(op)])||0;pending.push(op)}}}lastLocal=clone(next);persist();status();flush()}
async function init(){
  // Local-storage failures must never prevent a network connection or first render.
  try {
    const rawPending=localStorage.getItem('slow-think-v2-pending'),rawCache=localStorage.getItem('slow-think-v2-cache');
    const parsedPending=JSON.parse(rawPending||'[]'),parsedCache=JSON.parse(rawCache||'{"records":{},"revisions":{},"version":-1}');
    if(Array.isArray(parsedPending))pending=parsedPending.filter(op=>op&&typeof op.day==='string'&&Number.isInteger(op.problem)&&['planned','done'].includes(op.field)&&typeof op.value==='boolean');
    if(parsedCache&&parsedCache.records&&typeof parsedCache.records==='object'){
      const valid={};for(const [day,r] of Object.entries(parsedCache.records))if(r&&Array.isArray(r.list)&&Array.isArray(r.done))valid[day]={list:r.list.filter(Number.isInteger),done:r.done.filter(Number.isInteger)};
      snapshot={records:valid,revisions:parsedCache.revisions||{},plan:parsedCache.plan,planRevisions:parsedCache.planRevisions||{},version:parsedCache.version||0};
    }
    if((rawPending||rawCache)&&!localStorage.getItem('slow-think-v2-recovery-backup'))localStorage.setItem('slow-think-v2-recovery-backup',JSON.stringify({pending:rawPending,cache:rawCache}));
    const old=localStorage.getItem('slow-think-v1');
    if(old&&!localStorage.getItem('slow-think-v1-backup-before-sync'))localStorage.setItem('slow-think-v1-backup-before-sync',old);
    if(old&&!localStorage.getItem('slow-think-v2-imported')){const parsed=JSON.parse(old);if(parsed&&Object.values(parsed).some(r=>r&&(r.list?.length||r.done?.length)))legacy=parsed}
  } catch { /* Original storage keys remain intact. SQLite can still be read. */ }
  records=overlay(snapshot.records);lastLocal=clone(records);render();status();
  try{accept(await request('/api/progress'),false)}catch{connected=false}
  render();status();flush();
  setInterval(()=>{if(!document.hidden)flush()},10000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)flush()});
}
async function joinRoute(routeId){if(pending.length){await flush();if(pending.length)throw Error('请先同步待提交记录或解决冲突，再加入路线。')}const response=await request('/api/plan/route',{routeId,operationId:id()});accept(response.snapshot,true);return response.result}
return{save,init,status,flush,joinRoute};})();
